        if name in pins:
            rows = [row for row in rows if row["version"] == pins[name]]
        return rows

    def add_interval(limits, name, lower, upper):
        if name in limits:
            old_lower, old_upper = limits[name]
            lower = max(lower, old_lower)
            upper = min(upper, old_upper)
        if lower > upper:
            return False
        limits[name] = (lower, upper)
        return True

    def upper_bound(current, limits):
        bound = []
        for name in names:
            if name in current:
                bound.append(current[name]["version"])
            else:
                versions = [row["version"] for row in rows_for(name, limits)]
                if name in limits:
                    bound.append(max(versions) if versions else float("-inf"))
                else:
                    bound.append(max([-1, *versions]))
        return tuple(bound)

